export function totalAfterDiscount(prices: number[], percent: number): number {
  const subtotal = prices.reduce((sum, price) => sum + price, 0);
  return subtotal * (1 - percent / 100);
}

import { totalAfterDiscount } from "../math/prices";
export function cartLabel(prices: number[]) {
  return "Total: " + totalAfterDiscount(prices, 20).toFixed(2);
}
